export const buildServer = (
  options: { logger?: FastifyServerOptions['logger']; models?: typeof models } = {}
): FastifyInstance => {
  const fastify = Fastify({ logger: options.logger ?? defaultLogger });

  // Register all routes with /api prefix
  fastify.register(healthRoutes, { prefix: '/api' });
  fastify.register(rootRoutes, { prefix: '/api' });
  fastify.register(personasRoutes, { prefix: '/api' });
  fastify.register(aiRoutes, { prefix: '/api/ai' });
  fastify.register(generateRoutes, { prefix: '/api/generate' });
  fastify.register(streamTextRoutes, { prefix: '/api/stream-text' });
  fastify.register(streamObjectRoutes, { prefix: '/api/stream-object' });
  fastify.register(feedbackRoutes, { prefix: '/api/feedback' });
  fastify.register(userRoutes, { prefix: '/api/users' });

  return fastify;
};

