// Schema for the UUID parameter
const UuidParamSchema = z.object({
  uuid: z.string().uuid(),
});

export async function streamTextRoutes(server: FastifyInstance) {
  // Every route here reads or generates a user's chat, so none may run without an authenticated user.
  server.addHook('onRequest', requireUser);

  // Route for creating a new chat or continuing an existing one with UUID in URL path
  server.withTypeProvider<ZodTypeProvider>().route({
    method: 'POST',
    url: '/chat/:uuid',
    schema: {
      body: CommandRequestSchema,
      params: UuidParamSchema,
    },
    handler: async (request, reply) => {
      const userId = request.user?.id;
      const { uuid } = request.params;

      if (!userId) {
        return reply.code(401).send({ error: 'Unauthorized' });
      }

      return reply.send({});
    },
  });
}

